BEGIN
    LOCK TABLE public.ncm IN SHARE MODE;
    LOCK TABLE public.legislacao, public.aliquotas, public.beneficios IN SHARE ROW EXCLUSIVE MODE;
    IF EXISTS (
        SELECT 1 FROM (
            SELECT p->>'chave_ncm' AS codigo FROM jsonb_array_elements(carga->'aliquotas') p
            UNION ALL SELECT p->>'chave_ncm' FROM jsonb_array_elements(carga->'beneficios') p
            UNION ALL SELECT p->'depois'->>'chave_ncm' FROM jsonb_array_elements(carga->'revisoes'->'aliquotas') p
            UNION ALL SELECT p->'depois'->>'chave_ncm' FROM jsonb_array_elements(carga->'revisoes'->'beneficios') p
        ) a LEFT JOIN public.ncm n ON n.ncm=a.codigo AND upper(trim(n.ativo))='SIM'
        WHERE n.ncm IS NULL
    ) THEN RAISE EXCEPTION 'NCM ausente ou inativo; carga cancelada'; END IF;
    IF carga->>'hash_ncm' IS NOT NULL AND
       (SELECT md5(string_agg(ncm||'|'||coalesce(descricao_oficial,'')||'|'||coalesce(ativo,''),E'\n' ORDER BY ncm)) FROM public.ncm)
       IS DISTINCT FROM carga->>'hash_ncm'
    THEN RAISE EXCEPTION 'Catálogo NCM mudou; revisar a classificação'; END IF;
    IF EXISTS (
        SELECT 1 FROM (
            SELECT p->>'id_legislacao' AS id FROM jsonb_array_elements(carga->'aliquotas') p
            UNION ALL SELECT p->>'id_legislacao' FROM jsonb_array_elements(carga->'beneficios') p
            UNION ALL SELECT p->'depois'->>'id_legislacao' FROM jsonb_array_elements(carga->'revisoes'->'aliquotas') p
            UNION ALL SELECT p->'depois'->>'id_legislacao' FROM jsonb_array_elements(carga->'revisoes'->'beneficios') p
        ) a LEFT JOIN public.legislacao l ON l.id_legislacao=a.id AND upper(trim(l.ativo))='SIM'
        WHERE l.id_legislacao IS NULL AND NOT EXISTS
            (SELECT 1 FROM jsonb_array_elements(carga->'legislacao') p
             WHERE p->>'id_legislacao'=a.id AND p->>'ativo'='SIM')
    ) THEN RAISE EXCEPTION 'Fundamento ausente ou inativo; carga cancelada'; END IF;

    IF EXISTS (SELECT 1 FROM jsonb_array_elements(carga->'legislacao') p
        JOIN public.legislacao t ON t.id_legislacao=p->>'id_legislacao'
        WHERE NOT to_jsonb(t) @> p)
    THEN RAISE EXCEPTION 'Conflito na inserção em legislacao; carga cancelada'; END IF;

    IF EXISTS (SELECT 1 FROM jsonb_array_elements(carga->'aliquotas') p
        JOIN public.aliquotas t ON t.id_regra=p->>'id_regra'
        WHERE NOT to_jsonb(t) @> p)
    THEN RAISE EXCEPTION 'Conflito na inserção em aliquotas; carga cancelada'; END IF;

    IF EXISTS (SELECT 1 FROM jsonb_array_elements(carga->'revisoes'->'aliquotas') p
        LEFT JOIN public.aliquotas t ON t.id_regra=p->'antes'->>'id_regra'
        WHERE t.id_regra IS NULL OR (to_jsonb(t) IS DISTINCT FROM p->'antes'
                              AND to_jsonb(t) IS DISTINCT FROM p->'depois'))
    THEN RAISE EXCEPTION 'Conflito na revisão de aliquotas; carga cancelada'; END IF;

    IF EXISTS (SELECT 1 FROM jsonb_array_elements(carga->'beneficios') p
        JOIN public.beneficios t ON t.id_beneficio=p->>'id_beneficio'
        WHERE NOT to_jsonb(t) @> p)
    THEN RAISE EXCEPTION 'Conflito na inserção em beneficios; carga cancelada'; END IF;

    IF EXISTS (SELECT 1 FROM jsonb_array_elements(carga->'revisoes'->'beneficios') p
        LEFT JOIN public.beneficios t ON t.id_beneficio=p->'antes'->>'id_beneficio'
        WHERE t.id_beneficio IS NULL OR (to_jsonb(t) IS DISTINCT FROM p->'antes'
                              AND to_jsonb(t) IS DISTINCT FROM p->'depois'))
    THEN RAISE EXCEPTION 'Conflito na revisão de beneficios; carga cancelada'; END IF;

    IF EXISTS (SELECT 1 FROM public.aliquotas t
        JOIN jsonb_array_elements(carga->'aliquotas') p ON t.chave_ncm=p->>'chave_ncm'
        WHERE t.id_regra <> p->>'id_regra')
    THEN RAISE EXCEPTION 'Outro cadastro surgiu no NCM alvo; revisar antes'; END IF;

    INSERT INTO public.legislacao
        SELECT * FROM jsonb_populate_recordset(NULL::public.legislacao,carga->'legislacao')
        ON CONFLICT (id_legislacao) DO NOTHING;

    INSERT INTO public.aliquotas
        SELECT * FROM jsonb_populate_recordset(NULL::public.aliquotas,carga->'aliquotas')
        ON CONFLICT (id_regra) DO NOTHING;

    UPDATE public.aliquotas t SET (chave_ncm,tipo_correspondencia,descricao_regra,palavras_chave,aliquota_icms,adicional_percentual,id_legislacao,regra_consolidada_id,evidencia_ncm_id,vigencia_inicio,vigencia_fim,observacao,ativo,exige_descricao) =
        (SELECT r.chave_ncm,r.tipo_correspondencia,r.descricao_regra,r.palavras_chave,r.aliquota_icms,r.adicional_percentual,r.id_legislacao,r.regra_consolidada_id,r.evidencia_ncm_id,r.vigencia_inicio,r.vigencia_fim,r.observacao,r.ativo,r.exige_descricao
         FROM jsonb_populate_record(NULL::public.aliquotas,p->'depois') r)
    FROM jsonb_array_elements(carga->'revisoes'->'aliquotas') p
    WHERE t.id_regra=p->'antes'->>'id_regra' AND to_jsonb(t) IS DISTINCT FROM p->'depois';

    INSERT INTO public.beneficios
        SELECT * FROM jsonb_populate_recordset(NULL::public.beneficios,carga->'beneficios')
        ON CONFLICT (id_beneficio) DO NOTHING;

    UPDATE public.beneficios t SET (chave_ncm,tipo_correspondencia,descricao_regra,palavras_chave,tipo_beneficio,percentual_reducao_bc,carga_efetiva,credito_outorgado_percentual,condicoes,id_legislacao,regra_consolidada_id,evidencia_ncm_id,vigencia_inicio,vigencia_fim,observacao,ativo,exige_descricao,grupo_beneficio,aplicacao,escopo_operacao,cbenef) =
        (SELECT r.chave_ncm,r.tipo_correspondencia,r.descricao_regra,r.palavras_chave,r.tipo_beneficio,r.percentual_reducao_bc,r.carga_efetiva,r.credito_outorgado_percentual,r.condicoes,r.id_legislacao,r.regra_consolidada_id,r.evidencia_ncm_id,r.vigencia_inicio,r.vigencia_fim,r.observacao,r.ativo,r.exige_descricao,r.grupo_beneficio,r.aplicacao,r.escopo_operacao,r.cbenef
         FROM jsonb_populate_record(NULL::public.beneficios,p->'depois') r)
    FROM jsonb_array_elements(carga->'revisoes'->'beneficios') p
    WHERE t.id_beneficio=p->'antes'->>'id_beneficio' AND to_jsonb(t) IS DISTINCT FROM p->'depois';
END
$finalizacao$;
